package org.apache.commons.csv;

import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.math.*;
import java.sql.ResultSet;
import java.sql.ResultSetMetaData;
import java.sql.SQLException;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class CSVPrinter_printRecords_TriageGen1Test {









    @Test(expected = IOException.class)
    public void testPrintRecords_ThrowsIOException() throws Exception {
        // Use an Appendable that throws IOException
        Appendable errorAppendable = new Appendable() {
            @Override
            public Appendable append(CharSequence csq) throws IOException {
                throw new IOException("Write error");
            }
            @Override
            public Appendable append(CharSequence csq, int start, int end) throws IOException {
                throw new IOException("Write error");
            }
            @Override
            public Appendable append(char c) throws IOException {
                throw new IOException("Write error");
            }
        };

        CSVPrinter printer = new CSVPrinter(errorAppendable, CSVFormat.DEFAULT);
        ResultSet resultSet = mock(ResultSet.class);
        ResultSetMetaData metaData = mock(ResultSetMetaData.class);

        when(resultSet.getMetaData()).thenReturn(metaData);
        when(metaData.getColumnCount()).thenReturn(1);
        when(resultSet.next()).thenReturn(true);
        when(resultSet.getString(1)).thenReturn("data");

        printer.printRecords(resultSet);
        printer.close();
    }
}
